namespace marketComparison {
namespace {
void need(bool ok,QString message){if(!ok)throw std::runtime_error(message.toUtf8().constData());}
QString now(){return QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs);}
void validate(QJsonObject catalog){need(catalog["schema"]=="native-comparison-region-catalog/v1"&&catalog["taxonomy"]=="region"&&catalog["provider"]=="eastmoney-public-board"&&catalog["sourceUrl"]==regionCatalogUrl().toString()&&catalog["coverageComplete"]==true&&catalog["sourceTime"].isNull(),"地区目录身份/来源/完整性无效");auto t=catalog["checkedAt"].toString();need(QDateTime::fromString(t,Qt::ISODateWithMs).isValid()&&(t.endsWith('Z')||QRegularExpression("[+-]\\d{2}:\\d{2}$").match(t).hasMatch()),"地区目录读取时间无效");auto items=catalog["items"].toArray();need(!items.isEmpty()&&items.size()<=500&&items.size()==catalog["declaredTotal"].toInt(),"地区目录行数与声明不符");QSet<QString>seen;for(auto v:items){auto row=v.toObject();auto code=row["code"].toString();boardSeries::query("region",code);need(row["provider"]==catalog["provider"]&&row["taxonomy"]=="region"&&row["key"]=="eastmoney-region:"+code&&row["providerId"]=="90."+code&&!row["name"].toString().trimmed().isEmpty()&&row["name"].toString().size()<=100&&!seen.contains(code),"地区目录行身份冲突");seen.insert(code);}}
}
QUrl regionCatalogUrl(){QUrl url("https://push2.eastmoney.com/api/qt/clist/get");QUrlQuery q;for(auto pair:{qMakePair("pn","1"),qMakePair("pz","500"),qMakePair("po","1"),qMakePair("np","1"),qMakePair("ut","bd1d9ddb04089700cf9c27f6f7426281"),qMakePair("fltt","2"),qMakePair("invt","2"),qMakePair("fid","f12"),qMakePair("fs","m:90+t:1+f:!50"),qMakePair("fields","f12,f14")})q.addQueryItem(pair.first,pair.second);url.setQuery(q);return url;}
QJsonObject parseRegionCatalog(const QByteArray&bytes,const QString&checkedAt){need(!bytes.isEmpty()&&bytes.size()<=1024*1024&&QString::fromUtf8(bytes).toUtf8()==bytes,"地区目录为空、超1MiB或非UTF8");QJsonParseError error;auto doc=QJsonDocument::fromJson(bytes,&error);need(error.error==QJsonParseError::NoError&&doc.isObject(),"地区目录JSON损坏");auto root=doc.object(),data=root["data"].toObject();need(root["rc"]==0&&data["diff"].isArray()&&data["total"].isDouble(),"地区目录状态/数量无效");double count=data["total"].toDouble();auto raw=data["diff"].toArray();need(std::isfinite(count)&&count>=1&&count<=500&&std::floor(count)==count&&raw.size()==count,"地区目录未完整覆盖声明数量，未按同名补齐");QJsonArray items;for(auto v:raw){need(v.isObject(),"地区目录行不是对象");auto row=v.toObject();auto code=row["f12"].toString(),name=row["f14"].toString().trimmed();items.append(QJsonObject{{"key","eastmoney-region:"+code},{"name",name},{"taxonomy","region"},{"code",code},{"provider","eastmoney-public-board"},{"providerId","90."+code},{"capabilities",QJsonObject{{"daily",true},{"intraday",false}}}});}QJsonObject result{{"schema","native-comparison-region-catalog/v1"},{"taxonomy","region"},{"provider","eastmoney-public-board"},{"sourceUrl",regionCatalogUrl().toString()},{"sourceTime",QJsonValue(QJsonValue::Null)},{"checkedAt",checkedAt},{"declaredTotal",int(count)},{"coverageComplete",true},{"items",items}};validate(result);return result;}
RegionCatalogFeed::RegionCatalogFeed(QString directory,bool allow,QObject*parent,QNetworkAccessManager*transport):QObject(parent),file(QDir(directory).filePath("region-catalog-v1.json")),permitted(allow),network(transport?transport:new QNetworkAccessManager(this)){}
RegionCatalogFeed::~RegionCatalogFeed(){cancel();}
QJsonObject RegionCatalogFeed::read()const{QFile f(file);if(!f.exists())return {};need(f.open(QIODevice::ReadOnly)&&f.size()<=2*1024*1024,"地区缓存不可读或超限");QJsonParseError e;auto doc=QJsonDocument::fromJson(f.readAll(),&e);need(e.error==QJsonParseError::NoError&&doc.isObject(),"地区缓存损坏，未重建");auto root=doc.object();need(root["schema"]=="native-comparison-region-cache/v1","地区缓存schema无效");if(root.contains("catalog"))validate(root["catalog"].toObject());return root;}
void RegionCatalogFeed::cancel(){++epoch;if(reply){auto old=reply;reply=nullptr;old->disconnect(this);old->abort();old->deleteLater();}bytes.clear();}
void RegionCatalogFeed::start(){cancel();need(permitted,"此运行禁用公开源目录请求");QNetworkRequest request(regionCatalogUrl());request.setRawHeader("Referer","https://quote.eastmoney.com/");request.setRawHeader("User-Agent","Mozilla/5.0 StockNative/1");request.setAttribute(QNetworkRequest::RedirectPolicyAttribute,QNetworkRequest::ManualRedirectPolicy);request.setTransferTimeout(10000);auto ticket=epoch;reply=network->get(request);auto*current=reply.data();auto*deadline=new QTimer(current);deadline->setSingleShot(true);deadline->start(12000);connect(deadline,&QTimer::timeout,current,[current]{current->setProperty("regionError","地区目录读取超过12秒");current->abort();});connect(current,&QIODevice::readyRead,this,[this,current,ticket]{if(epoch!=ticket||reply!=current)return;bytes+=current->readAll();if(bytes.size()>1024*1024){current->setProperty("regionError","地区目录响应超过1MiB");current->abort();}});connect(current,&QNetworkReply::finished,this,[this,current,ticket]{if(epoch!=ticket||reply!=current){current->deleteLater();return;}bytes+=current->readAll();reply=nullptr;QString problem=current->property("regionError").toString();auto status=current->attribute(QNetworkRequest::HttpStatusCodeAttribute).toInt();if(problem.isEmpty()&&(status!=200||current->error()!=QNetworkReply::NoError))problem=QString("HTTP %1 · %2").arg(status).arg(current->errorString());current->deleteLater();auto body=bytes;bytes.clear();if(!problem.isEmpty()){publish({},problem);return;}try{publish(parseRegionCatalog(body,now()),{});}catch(const std::exception&e){publish({},e.what());}});}
void RegionCatalogFeed::publish(QJsonObject catalog,const QString&error){QJsonObject receipt;try{need(QDir().mkpath(QFileInfo(file).absolutePath()),"地区缓存目录不可用");QLockFile lock(file+".lock");need(lock.tryLock(500),"地区缓存正忙");receipt=read();receipt["schema"]="native-comparison-region-cache/v1";if(!catalog.isEmpty())receipt["catalog"]=catalog;receipt["lastAttempt"]=QJsonObject{{"checkedAt",now()},{"status",error.isEmpty()?"success":"failed"},{"error",error.left(1000)},{"sourceUrl",regionCatalogUrl().toString()}};auto raw=QJsonDocument(receipt).toJson(QJsonDocument::Compact);need(raw.size()<=2*1024*1024,"地区缓存超过2MiB");QSaveFile f(file);need(f.open(QIODevice::WriteOnly)&&f.write(raw)==raw.size()&&f.commit(),"地区目录原子保存失败，旧数据保留");}catch(const std::exception&e){receipt["saveError"]=QString::fromUtf8(e.what());if(!catalog.isEmpty())receipt["catalog"]=catalog;}emit finished(receipt);}
}
